31	    private static void validate(int[] values) {
32	        if (values == null) {
33	            throw new IllegalArgumentException("values must not be null");
34	        }
35	    }
36	
37	    private static void sortValuesInPlace(int[] values) {
38	        int end = values.length - 1;
39	        while (end > 0) {
40	            int lastSwapIndex = bubblePass(values, end);
41	            if (lastSwapIndex == 0) {
42	                return;
43	            }
44	            end = lastSwapIndex - 1;
45	        }
46	    }
47	
48	    private static int bubblePass(int[] values, int endExclusive) {
49	        int lastSwapIndex = 0;
50	
51	        for (int index = 0; index < endExclusive; index++) {
52	            if (isOutOfOrder(values, index)) {
53	                swap(values, index, index + 1);
54	                lastSwapIndex = index + 1;
55	            }
56	        }
57	
58	        return lastSwapIndex;
59	    }
60	
61	    private static boolean isOutOfOrder(int[] values, int index) {
62	        return values[index] > values[index + 1];
63	    }
64	
65	    private static void swap(int[] values, int leftIndex, int rightIndex) {
66	        int temp = values[leftIndex];
67	        values[leftIndex] = values[rightIndex];
68	        values[rightIndex] = temp;
69	    }
70	
71	    private static String formatArray(int[] values) {
72	        StringJoiner joiner = new StringJoiner(" ");
73	
74	        for (int value : values) {
75	            joiner.add(Integer.toString(value));
76	        }
77	
78	        return joiner.toString();
79	    }
